import sys


def parse(tile):
    return int(tile[0]), tile[1]


def is_mentsu(tiles):
    nums = [t[0] for t in tiles]
    suits = [t[1] for t in tiles]

    # Koutsu
    if tiles[0] == tiles[1] == tiles[2]:
        return True

    # Shuntsu
    if suits[0] == suits[1] == suits[2]:
        nums.sort()
        if nums[0] + 1 == nums[1] and nums[1] + 1 == nums[2]:
            return True

    return False


def pair_needs_one(a, b):
    na, sa = a
    nb, sb = b

    # Can complete a triplet
    if a == b:
        return True

    # Can complete a sequence
    if sa == sb and abs(na - nb) <= 2:
        return True

    return False


def main():
    tiles_str = sys.stdin.read().strip().split()
    tiles = [parse(x) for x in tiles_str]

    if is_mentsu(tiles):
        print(0)
        return

    for i in range(3):
        for j in range(i + 1, 3):
            if pair_needs_one(tiles[i], tiles[j]):
                print(1)
                return

    print(2)


