import sys

sys.setrecursionlimit(1_000_000)

def main():
    input = sys.stdin.readline
    n, k = map(int, input().split())
    main_courses = list(map(int, input().split()))

    deps = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        line = list(map(int, input().split()))
        t = line[0]
        if t:
            deps[i] = line[1:]

    state = [0] * (n + 1)  # 0 = unvisited, 1 = visiting, 2 = done
    order = []
    possible = True

    def dfs(v):
        nonlocal possible
        state[v] = 1
        for u in deps[v]:
            if state[u] == 0:
                dfs(u)
                if not possible:
                    return
            elif state[u] == 1:
                possible = False
                return
        state[v] = 2
        order.append(v)

    for c in main_courses:
        if state[c] == 0:
            dfs(c)
            if not possible:
                print(-1)
                return
        elif state[c] == 1:
            print(-1)
            return

    print(len(order))
    print(*order)

if __name__ == "__main__":
    main()

