def valid_horizontal(grid, n, m):
    if n % 3 != 0:
        return False
    h = n // 3
    colors = []
    for k in range(3):
        c = grid[k * h][0]
        colors.append(c)
        for i in range(k * h, (k + 1) * h):
            for j in range(m):
                if grid[i][j] != c:
                    return False
    return len(set(colors)) == 3


def valid_vertical(grid, n, m):
    if m % 3 != 0:
        return False
    w = m // 3
    colors = []
    for k in range(3):
        c = grid[0][k * w]
        colors.append(c)
        for i in range(n):
            for j in range(k * w, (k + 1) * w):
                if grid[i][j] != c:
                    return False
    return len(set(colors)) == 3


def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = data[1:1 + n]

    if valid_horizontal(grid, n, m) or valid_vertical(grid, n, m):
        print("YES")
    else:
        print("NO")


if __name__ == "__main__":
    solve()

