def solve():
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()

    total_g = s.count('G')
    if total_g == 0:
        print(0)
        return

    runs = []  # list of (char, length)
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        runs.append((s[i], j - i))
        i = j

    ans = 0

    # Existing runs, possibly extend one by swapping in one extra G from elsewhere.
    for ch, length in runs:
