import sys
from math import isqrt, gcd


def factorize(n):
    fac = {}
    while n % 2 == 0:
        fac[2] = fac.get(2, 0) + 1
        n //= 2
    f = 3
    while f * f <= n:
        while n % f == 0:
            fac[f] = fac.get(f, 0) + 1
            n //= f
        f += 2
    if n > 1:
        fac[n] = fac.get(n, 0) + 1
    return fac


def gen_divisors_from_factors(items, idx=0, cur=1, out=None):
    if out is None:
        out = []
    if idx == len(items):
        out.append(cur)
        return out
    p, e = items[idx]
    val = 1
    for _ in range(e + 1):
        gen_divisors_from_factors(items, idx + 1, cur * val, out)
        val *= p
    return out


def phi_from_factorization(fac):
    res = 1
    for p, e in fac.items():
        res *= (p - 1) * (p ** (e - 1))
    return res


def multiplicative_order(x, n):
    if n == 1:
        return 1
    phifac = factorize(n)
    phi = phi_from_factorization(phifac)
    order = phi
    order_factors = factorize(order)
    for p in order_factors:
        while order % p == 0 and pow(x, order // p, n) == 1:
            order //= p
    return order


