    M = [[0] * m for _ in range(m)]
    for st in range(m):
        for bit in range(2):
            nx = go[st][bit]
            if nx < m:
                M[st][nx] += 1

    Mn = mat_pow(M, n)
    avoid = sum(Mn[i][i] for i in range(m))
    ans = (1 << n) - avoid
    print(ans)


