import math
import sys


def score_right(a, b, c):
    # value = a^(b^c), compare by L = (b^c) * ln(a)
    la = math.log(a)
    if abs(la) < 1e-15:
        return (0, 0.0)  # value == 1
    if la > 0:
        # L > 0, value > 1; compare by ln(L) = c*ln(b) + ln(ln(a))
        return (1, c * math.log(b) + math.log(la))
    else:
        # L < 0, value < 1; larger value means smaller |L|
        # compare by -ln(|L|) = -(c*ln(b) + ln(-ln(a)))
        return (-1, -(c * math.log(b) + math.log(-la)))


def score_left(a, b, c):
    # value = (a^b)^c = a^(bc), compare by L = bc * ln(a)
    la = math.log(a)
    if abs(la) < 1e-15:
        return (0, 0.0)  # value == 1
    t = math.log(b) + math.log(c)  # ln(bc)
    if la > 0:
        # L > 0, value > 1; compare by ln(L) = ln(bc) + ln(ln(a))
        return (1, t + math.log(la))
    else:
        # L < 0, value < 1; larger value means smaller |L|
        return (-1, -(t + math.log(-la)))


def main():
    data = sys.stdin.read().strip().split()
    x, y, z = map(float, data)

    candidates = [
        (score_right(x, y, z), 'x^y^z'),
        (score_right(x, z, y), 'x^z^y'),
        (score_left(x, y, z), '(x^y)^z'),
        (score_left(x, z, y), '(x^z)^y'),
        (score_right(y, x, z), 'y^x^z'),
        (score_right(y, z, x), 'y^z^x'),
        (score_left(y, x, z), '(y^x)^z'),
        (score_left(y, z, x), '(y^z)^x'),
        (score_right(z, x, y), 'z^x^y'),
        (score_right(z, y, x), 'z^y^x'),
        (score_left(z, x, y), '(z^x)^y'),
        (score_left(z, y, x), '(z^y)^x'),
    ]

    best_score, best_expr = candidates[0]
    for sc, expr in candidates[1:]:
        if sc > best_score:
            best_score, best_expr = sc, expr

    print(best_expr)


