            go[st][bit] = j
    return go


def mat_mul(a, b):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        ai = a[i]
        ri = res[i]
        for k in range(n):
            if ai[k] == 0:
                continue
            aik = ai[k]
            bk = b[k]
            for j in range(n):
                if bk[j]:
                    ri[j] += aik * bk[j]
    return res


def mat_pow(mat, exp):
    n = len(mat)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    while exp > 0:
        if exp & 1:
            res = mat_mul(res, mat)
        mat = mat_mul(mat, mat)
        exp >>= 1
    return res


def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    s = data[1].strip()
    m = len(s)

    go = build_automaton(s)

    # Transition matrix on non-terminal KMP states 0..m-1.
    # Edges that would complete a match are forbidden.
    M = [[0] * m for _ in range(m)]
    for st in range(m):
        for bit in range(2):
            nx = go[st][bit]
            if nx < m:
                M[st][nx] += 1

    Mn = mat_pow(M, n)
    avoid = sum(Mn[i][i] for i in range(m))
    ans = (1 << n) - avoid
    print(ans)


if __name__ == "__main__":
    main()

