def egcd(a, b):
    if b == 0:
        return (a, 1, 0)
    g, x1, y1 = egcd(b, a % b)
    return (g, y1, x1 - (a // b) * y1)


def crt(a1, b1, a2, b2):
    # Solve x ≡ b1 (mod a1), x ≡ b2 (mod a2)
    g, x, y = egcd(a1, a2)
