    best_val = int(x_str)
    best_sum = digit_sum_str(x_str)

    n = len(x_str)
    for i, ch in enumerate(x_str):
        if ch == '0':
            continue
        # Decrease this digit by 1 and make the suffix all 9s.
        prefix = x_str[:i]
        new_digit = str(int(ch) - 1)
        candidate_str = prefix + new_digit + '9' * (n - i - 1)
        candidate_val = int(candidate_str)
        if candidate_val <= 0:
            continue
        s = digit_sum_str(candidate_str)
        if s > best_sum or (s == best_sum and candidate_val > best_val):
            best_sum = s
            best_val = candidate_val

    print(best_val)


