def score_right(a, b, c):
    # value = a^(b^c), compare by L = (b^c) * ln(a)
    la = math.log(a)
    if abs(la) < 1e-15:
        return (0, 0.0)  # value == 1
    if la > 0:
        # L > 0, value > 1; compare by ln(L) = c*ln(b) + ln(ln(a))
        return (1, c * math.log(b) + math.log(la))
    else:
        # L < 0, value < 1; larger value means smaller |L|
        # compare by -ln(|L|) = -(c*ln(b) + ln(-ln(a)))
        return (-1, -(c * math.log(b) + math.log(-la)))


