import sys


def prefix_function(p):
    m = len(p)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i - 1]
        while j > 0 and p[i] != p[j]:
            j = pi[j - 1]
        if p[i] == p[j]:
            j += 1
        pi[i] = j
    return pi


def build_automaton(s):
    m = len(s)
    pi = prefix_function(s)
    go = [[0, 0] for _ in range(m)]
    for st in range(m):
        for bit in range(2):
            ch = str(bit)
            j = st
            while j > 0 and s[j] != ch:
                j = pi[j - 1]
            if s[j] == ch:
                j += 1
            go[st][bit] = j
    return go


def mat_mul(a, b):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        ai = a[i]
        ri = res[i]
        for k in range(n):
            if ai[k] == 0:
                continue
            aik = ai[k]
            bk = b[k]
            for j in range(n):
                if bk[j]:
                    ri[j] += aik * bk[j]
    return res


def mat_pow(mat, exp):
    n = len(mat)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    while exp > 0:
