def solve():
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()

    total_g = s.count('G')
    if total_g == 0:
        print(0)
        return

    runs = []  # list of (char, length)
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        runs.append((s[i], j - i))
        i = j

    ans = 0

    # Existing runs, possibly extend one by swapping in one extra G from elsewhere.
    for ch, length in runs:
        if ch == 'G':
            ans = max(ans, min(total_g, length + 1))

    # Merge two G-runs separated by exactly one S.
    for k in range(1, len(runs) - 1):
        ch, length = runs[k]
        if ch == 'S' and length == 1 and runs[k - 1][0] == 'G' and runs[k + 1][0] == 'G':
            merged = runs[k - 1][1] + runs[k + 1][1]
            if total_g > merged:
                merged += 1
            ans = max(ans, merged)

    print(ans)


