import sys


def feasible(rem, d, p):
    # Can we realize exactly rem ones using d single diagonal cells and p symmetric pairs?
    if rem < 0 or rem > d + 2 * p:
        return False
    if d == 0:
        return rem % 2 == 0
    return True


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = map(int, data)

    if k > n * n:
        print(-1)
        return

    # Total resources from current position onward while scanning upper triangle row-major.
    a = [[0] * n for _ in range(n)]

    # Precompute ordered list of upper-triangle positions.
    positions = []
    for i in range(n):
        for j in range(i, n):
            positions.append((i, j))

    total_diag = n
    total_pairs = n * (n - 1) // 2

    used_diag = 0
    used_pairs = 0
    rem = k

    for i, j in positions:
        d_left_after_skip = total_diag - used_diag - (1 if i == j else 0)
        p_left_after_skip = total_pairs - used_pairs - (0 if i == j else 1)

        if i == j:
            # Try to put 1 here if feasible for the suffix.
            if feasible(rem - 1, d_left_after_skip, p_left_after_skip):
                a[i][i] = 1
                rem -= 1
            used_diag += 1
        else:
            # Try to put a symmetric pair here if feasible.
            if feasible(rem - 2, d_left_after_skip, p_left_after_skip):
                a[i][j] = a[j][i] = 1
                rem -= 2
            used_pairs += 1

    if rem != 0:
        print(-1)
        return

    out = []
    for i in range(n):
        out.append(' '.join(map(str, a[i])) + ' ')
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    solve()

