import sys
import math


def egcd(a, b):
    if b == 0:
        return (a, 1, 0)
    g, x1, y1 = egcd(b, a % b)
    return (g, y1, x1 - (a // b) * y1)


def crt(a1, b1, a2, b2):
    # Solve x ≡ b1 (mod a1), x ≡ b2 (mod a2)
    g, x, y = egcd(a1, a2)
    diff = b2 - b1
    if diff % g != 0:
        return None

    lcm = a1 // g * a2
    m2 = a2 // g
    t = (diff // g) % m2
    k = (t * x) % m2
    r = (b1 + a1 * k) % lcm
    return r, lcm


def count_in_ap_interval(r, mod, lo, hi):
    if lo > hi:
        return 0
    first = r if r >= lo else r + ((lo - r + mod - 1) // mod) * mod
    if first > hi:
        return 0
    return (hi - first) // mod + 1


def main():
    data = sys.stdin.readline().split()
    if not data:
        return
    a1, b1, a2, b2, L, R = map(int, data)

    sol = crt(a1, b1, a2, b2)
    if sol is None:
        print(0)
        return

    r, mod = sol
    lo = max(L, b1, b2)
    hi = R
    print(count_in_ap_interval(r, mod, lo, hi))


if __name__ == "__main__":
    main()

