import sys


def valid_horizontal(grid, n, m):
    if n % 3 != 0:
        return False
    h = n // 3
    colors = []
    for k in range(3):
        c = grid[k * h][0]
        colors.append(c)
        for i in range(k * h, (k + 1) * h):
            for j in range(m):
                if grid[i][j] != c:
                    return False
    return len(set(colors)) == 3


def valid_vertical(grid, n, m):
    if m % 3 != 0:
        return False
    w = m // 3
    colors = []
    for k in range(3):
        c = grid[0][k * w]
